-- Initial catalog only: no fake accounts or password hashes are imported.
begin;

on conflict do nothing;
select setval(pg_get_serial_sequence('public.countries','countryID'), coalesce((select max("countryID") from public.countries),1));
select setval(pg_get_serial_sequence('public.genres','genreID'), coalesce((select max("genreID") from public.genres),1));
select setval(pg_get_serial_sequence('public.directors','directorID'), coalesce((select max("directorID") from public.directors),1));
select setval(pg_get_serial_sequence('public.actors','actorID'), coalesce((select max("actorID") from public.actors),1));
select setval(pg_get_serial_sequence('public.movies','movieID'), coalesce((select max("movieID") from public.movies),1));
select setval(pg_get_serial_sequence('public.ratings','ratingID'), coalesce((select max("ratingID") from public.ratings),1));
select setval(pg_get_serial_sequence('public.boxoffice','boxOfficeID'), coalesce((select max("boxOfficeID") from public.boxoffice),1));
select setval(pg_get_serial_sequence('public.movieactors','movieActorID'), coalesce((select max("movieActorID") from public.movieactors),1));
select setval(pg_get_serial_sequence('public.discounts','discountID'), coalesce((select max("discountID") from public.discounts),1));
commit;
